<template><div><h2>路网仿真</h2><el-card><el-form :model="form" inline><el-form-item label="任务名称"><el-input v-model="form.name" /></el-form-item><el-form-item><el-button type="primary" @click="run">启动仿真</el-button></el-form-item></el-form></el-card><el-card class="panel"><el-table :data="items"><el-table-column prop="name" label="任务"/><el-table-column prop="status" label="状态"/><el-table-column prop="progress" label="进度"/></el-table></el-card></div></template><script setup lang="ts">import {onMounted,ref} from 'vue'; import {api} from '../../api'; const form=ref({name:'晚高峰配时评估',intersectionIds:[],flowMultiplier:1}); const items=ref<Record<string,unknown>[]>([]); const load=async()=>{const r=await api.simulations();items.value=r.data.data||[]}; const run=async()=>{await api.createSimulation(form.value);await load()};onMounted(load)</script>
